// Build-time bridge: reads the `products` Firestore collection via the
// Firebase Admin SDK and writes a static data file the Astro site can
// import at build time. Same pattern as fetch-gallery.mjs — see that file
// for the credential/non-fatal-failure rationale, not repeated here.
//
// Run automatically via the "prebuild" npm script before `astro build`.
// Safe to run manually too: `node scripts/fetch-products.mjs`.
//
// Why this script exists (not just "seemed nice to have"): the Flutter
// admin app writes real products to Firestore with auto-generated document
// IDs. Before this script, astro/src/data/syncedProducts.js was a static
// spread-copy of hand-written, CSV-derived data with slug ids like
// 'blue-branches' — completely disconnected from what the admin app
// actually manages. That disconnect is also why server-side price
// verification wasn't possible before this existed (see
// firebase/functions/lib/pricing.js).

import admin from 'firebase-admin';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

const serviceAccountPath = path.join(
  __dirname,
  '..',
  '..',
  'firebase',
  'functions',
  'secrets',
  'serviceAccountKey.json'
);

/**
 * Lowercases, strips punctuation, and hyphenates a title into a URL-safe
 * slug — matches the convention the old hand-written products.js already
 * used for its `handle` values (e.g. "Blue Branches" -> "blue-branches"),
 * since Firestore's product docs have no handle field of their own.
 * @param {string} title
 * @returns {string}
 */
function slugify(title) {
  return (title || '')
    .toLowerCase()
    .replace(/['’]/g, '') // contractions collapse: "you're" -> "youre"
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

/**
 * Pure transform from a Firestore product document to the shape
 * astro/src/data/products.js's Product typedef expects. No Firestore calls
 * here — unit-testable without a live database, same as
 * fetch-gallery.mjs's docToGalleryPhoto.
 *
 * category/dimensions/features/tags/compareAtPrice default to safe empty
 * values rather than being invented — the Flutter admin app's Product model
 * doesn't collect those fields today, a known gap tracked separately, not
 * something to paper over with guessed data here.
 * @param {{ id: string, data: () => Record<string, any> }} doc
 */
export function docToProduct(doc) {
  const data = doc.data();
  const images = Array.isArray(data.imageUrls) && data.imageUrls.length > 0
    ? data.imageUrls
    : data.imageUrl
      ? [data.imageUrl]
      : [];

  return {
    id: doc.id,
    handle: slugify(data.title),
    title: data.title || '',
    description: data.description || '',
    price: typeof data.price === 'number' ? data.price : 0,
    compareAtPrice: null,
    images,
    tags: [],
    inStock: data.isActive !== false,
    category: '',
    dimensions: '',
    features: [],
    weight: typeof data.weight === 'number' ? data.weight : 0,
    seoTitle: '',
    seoDescription: '',
  };
}

/**
 * Disambiguates handle collisions (two products slugifying to the same
 * title) by suffixing every collision after the first with a short chunk
 * of its own Firestore doc id. Without this, getStaticPaths would silently
 * drop all but one product sharing a handle instead of erroring loudly.
 * @param {ReturnType<typeof docToProduct>[]} products
 */
export function dedupeHandles(products) {
  const seen = new Map();
  return products.map((product) => {
    const count = seen.get(product.handle) || 0;
    seen.set(product.handle, count + 1);
    if (count === 0) return product;
    const suffix = product.id.slice(-4);
    return { ...product, handle: `${product.handle}-${suffix}` };
  });
}

async function main() {
  if (!admin.apps.length) {
    const config = {};
    if (fs.existsSync(serviceAccountPath)) {
      config.credential = admin.credential.cert(
        JSON.parse(fs.readFileSync(serviceAccountPath, 'utf8'))
      );
      console.log('Using local service account for product fetch.');
    } else {
      console.log('Using default credentials for product fetch.');
      config.credential = admin.credential.applicationDefault();
    }
    admin.initializeApp(config);
  }

  const db = admin.firestore();
  const snapshot = await db
    .collection('products')
    .where('isActive', '==', true)
    .get();

  const products = dedupeHandles(snapshot.docs.map(docToProduct));

  const outPath = path.join(__dirname, '..', 'src', 'data', 'syncedProducts.js');
  const contents =
    `// AUTO-GENERATED by scripts/fetch-products.mjs at build time. Do not edit by hand.\n` +
    `// Helper functions below are kept for backward compatibility with\n` +
    `// astro/src/pages/api/products/*.js (sync.js, bulk-sync.js, [id].js) —\n` +
    `// those routes are redundant now that products come from Firestore at\n` +
    `// build time (see fetch-products.mjs's header comment), but haven't been\n` +
    `// removed yet. Mutations here never persist past this build, same as\n` +
    `// before this script existed — not a new limitation.\n` +
    `/** @type {import('./products.js').Product[]} */\n` +
    `export let syncedProducts = ${JSON.stringify(products, null, 2)};\n\n` +
    `export function addProduct(product) {\n` +
    `  syncedProducts.push(product);\n` +
    `  return product;\n` +
    `}\n\n` +
    `export function updateProduct(productId, updatedProduct) {\n` +
    `  const index = syncedProducts.findIndex((p) => p.id === productId);\n` +
    `  if (index >= 0) {\n` +
    `    syncedProducts[index] = { ...syncedProducts[index], ...updatedProduct };\n` +
    `    return syncedProducts[index];\n` +
    `  }\n` +
    `  return null;\n` +
    `}\n\n` +
    `export function deleteProduct(productId) {\n` +
    `  const index = syncedProducts.findIndex((p) => p.id === productId);\n` +
    `  if (index >= 0) {\n` +
    `    const deletedProduct = syncedProducts[index];\n` +
    `    syncedProducts.splice(index, 1);\n` +
    `    return deletedProduct;\n` +
    `  }\n` +
    `  return null;\n` +
    `}\n\n` +
    `export function getProduct(productId) {\n` +
    `  return syncedProducts.find((p) => p.id === productId);\n` +
    `}\n\n` +
    `export function getAllProducts() {\n` +
    `  return [...syncedProducts];\n` +
    `}\n\n` +
    `export function getProductByHandle(handle) {\n` +
    `  return syncedProducts.find((p) => p.handle === handle);\n` +
    `}\n\n` +
    `export function getInStockProducts() {\n` +
    `  return syncedProducts.filter((p) => p.inStock);\n` +
    `}\n`;

  fs.writeFileSync(outPath, contents);
  console.log(`Wrote ${products.length} product(s) to ${outPath}`);
}

// Same Windows-safe main-module check as fetch-gallery.mjs.
const isMainModule =
  process.argv[1] &&
  path.resolve(fileURLToPath(import.meta.url)) === path.resolve(process.argv[1]);

if (isMainModule) {
  main().catch((err) => {
    // Deliberately non-fatal, same rationale as fetch-gallery.mjs: a
    // transient Firestore hiccup shouldn't take down the whole deploy.
    console.error('[fetch-products] Failed to fetch products from Firestore — build will continue with the existing syncedProducts.js data.');
    console.error(err);
  });
}
